import { Component } from '@angular/core';
import * as CryptoJS from 'crypto-js';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss'],
})
export class AppComponent {
  title = 'EncryptDecrypt';

  encDecKey: string = '';
  encDecKeyIV: string = '';
  userPlainText: string = '';
  userEncryptedText: string = '';

  encryptedData: string = '';
  decryptedData: string = '';

  clearAll() {
    this.encDecKey = '';
    this.encDecKeyIV = '';
    this.clearEncryptDataFields();
    this.clearDecryptDataFields();
  }

  clearEncryptDataFields() {
    this.userPlainText = '';
    this.encryptedData = '';
  }

  clearDecryptDataFields() {
    this.userEncryptedText = '';
    this.decryptedData = '';
  }

  dataEncryptor(plainTextData: any) {
    if (plainTextData && this.encDecKey && this.encDecKeyIV) {
      const key = CryptoJS.enc.Hex.parse(this.encDecKey);
      const iv = CryptoJS.enc.Hex.parse(this.encDecKeyIV);
      const encrypted = CryptoJS.AES.encrypt(plainTextData.toString(), key, {
        iv: iv,
        mode: CryptoJS.mode.CBC,
        padding: CryptoJS.pad.Pkcs7,
      });
      this.encryptedData = encrypted.toString();
      return encrypted.toString();
    }
    return null;
  }

  dataDecryptor(encryptedData: any) {
    if (encryptedData && this.encDecKey) {
      const key = CryptoJS.enc.Hex.parse(this.encDecKey);
      const iv = CryptoJS.enc.Hex.parse(this.encDecKeyIV);
      const decrypted = CryptoJS.AES.decrypt(encryptedData.toString(), key, {
        iv: iv,
        mode: CryptoJS.mode.CBC,
        padding: CryptoJS.pad.Pkcs7,
      });
      this.decryptedData = decrypted.toString(CryptoJS.enc.Utf8);
      return decrypted.toString(CryptoJS.enc.Utf8);
    }
    return null;
  }

  textToCopy: string = '';
  pastedText: string = '';

  // Function to copy text to the clipboard
  copyToClipboard(): void {
    if (!this.textToCopy) {
      alert('Please enter text to copy!');
      return;
    }
    navigator.clipboard
      .writeText(this.textToCopy)
      .then(() => {
        alert('Text copied to clipboard!');
      })
      .catch((err) => {
        console.error('Failed to copy text: ', err);
      });
  }
}
<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Encryption/Decryption UI</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
</head>

<body>
  <div class="container">
    <div>
      <label for="form-title" class="form-label mb-4 d-flex justify-content-center">Angular Encryption/Decryption Using
        NPM&nbsp;
        <a href="https://www.npmjs.com/package/crypto-js" target="_blank">crypto-js</a></label>
    </div>
    <div class="key-section mb-4">
      <label for="key" class="form-label">Symmetric Key</label>
      <input type="text" id="key" class="form-control" placeholder="Enter symmetric key here" [(ngModel)]="encDecKey">
    </div>

    <div class="key-section mb-4">
      <label for="key" class="form-label">Symmetric IV Key</label>
      <input type="text" id="key" class="form-control" placeholder="Enter symmetric IV key here"
        [(ngModel)]="encDecKeyIV">
    </div>

    <div class="row">
      <div class="col-md-6">
        <label for="plaintext" class="form-label">Plain Text to Encrypt</label>
        <input type="text" id="plaintext" class="form-control" placeholder="Enter plain text"
          [(ngModel)]="userPlainText">
      </div>
      <div class="col-md-6">
        <label for="encryptedtext" class="form-label">Encrypted Text to Decrypt</label>
        <input type="text" id="encryptedtext" class="form-control" placeholder="Enter encrypted text"
          [(ngModel)]="userEncryptedText">
      </div>
    </div>

    <div class="row">
      <div class="col-md-6">
        <div class="row">
          <div class="col-md-6">
            <button type="button" class="btn btn-light" (click)="clearEncryptDataFields()">Clear</button>
          </div>
          <div class="col-md-6">
            <button id="encrypt-btn" class="btn btn-primary" (click)="dataEncryptor(userPlainText)">Encrypt</button>
          </div>
        </div>
      </div>
      <div class="col-md-6">

        <div class="row">
          <div class="col-md-6">
            <button type="button" class="btn btn-light" (click)="clearDecryptDataFields()">Clear</button>
          </div>
          <div class="col-md-6">
            <button id="decrypt-btn" class="btn btn-secondary"
              (click)="dataDecryptor(userEncryptedText)">Decrypt</button>
          </div>
        </div>
      </div>
    </div>

    <div class="row mt-4">
      <div class="col-md-6">
        <div class="label-section">
          <div class="row d-grid align-items-end justify-content-end text-center mb-0">
            <img src="assets/img/copy.svg" alt="copy" class="copy-icon">
          </div>
          Encrypted Value:
          <div id="encrypted-label" class="encrypted-label">
            {{encryptedData}}
          </div>
        </div>
      </div>
      <div class="col-md-6">
        <div class="label-section">
          <div class="row d-grid align-items-end justify-content-end text-center mb-0">
            <img src="assets/img/copy.svg" alt="copy" class="copy-icon">
          </div>
          Decrypted Value:
          <div id="decrypted-label" class="decrypted-label"> {{decryptedData}}</div>
        </div>
      </div>
    </div>

    <div class="d-flex justify-content-end">
      <button type="button" class="btn btn-danger" (click)="clearAll()">Clear All</button>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
</body>

</html>





